#!/usr/bin/env python3
"""Regenerate Gemini REST types and Claude capabilities from pinned LiteLLM.

Run with Python 3.11+ and rustfmt. The LiteLLM checkout must contain the vendored revision.
"""

import argparse
import ast
import json
import re
import subprocess
import tomllib
from pathlib import Path


CRATE = Path(__file__).resolve().parents[2]


SOURCE = "litellm/types/llms/vertex_ai.py"

# Project the types used by Bamboo. Keep the exported names of the LiteLLM
# TypedDicts so that each definition can be traced back to the pinned source.
FIELDS = {
    "RequestBody": ("contents", "system_instruction", "tools", "generationConfig"),
    "SystemInstructions": ("parts",),
    "ContentType": ("role", "parts"),
    "PartType": (
        "text", "inline_data", "file_data", "function_call", "function_response", "thoughtSignature",
    ),
    "BlobType": ("mime_type", "data"),
    "FileDataType": ("mime_type", "file_uri"),
    "FunctionCall": ("id", "name", "args"),
    "FunctionResponse": ("id", "name", "response", "parts"),
    "FunctionResponsePartType": ("inline_data", "file_data"),
    "Tools": ("function_declarations",),
    "FunctionDeclaration": ("name", "description", "parameters"),
    "GenerationConfig": ("max_output_tokens", "thinkingConfig"),
    "GeminiThinkingConfig": ("includeThoughts", "thinkingBudget", "thinkingLevel"),
}

# LiteLLM assembles a tools array in the HTTP body. The REST API also allows
# FileData without a MIME type and accepts full JSON Schema for declarations.
REST_FIELDS = {
    ("RequestBody", "tools"): ("tools", "Vec<Tools>", False),
    ("FileDataType", "mime_type"): ("mime_type", "String", False),
    ("FunctionDeclaration", "parameters"): ("parameters_json_schema", "Value", False),
}

THINKING_BUDGETS = {
    "DEFAULT_REASONING_EFFORT_LOW_THINKING_BUDGET": "LOW_THINKING_BUDGET",
    "DEFAULT_REASONING_EFFORT_MEDIUM_THINKING_BUDGET": "MEDIUM_THINKING_BUDGET",
    "DEFAULT_REASONING_EFFORT_HIGH_THINKING_BUDGET": "HIGH_THINKING_BUDGET",
}


def rust_type(annotation):
    match annotation:
        case ast.Constant(value=str() as forward_reference):
            return rust_type(ast.parse(forward_reference, mode="eval").body)
        case ast.Name(id=("str" | "int" | "bool") as name):
            return {"str": "String", "int": "i64", "bool": "bool"}[name]
        case ast.Name(id="dict") | ast.BinOp(op=ast.BitOr()):
            return "Value"
        case ast.Name(id=name) if name in FIELDS:
            return name
        case ast.Subscript(value=ast.Name(id="list"), slice=element):
            return f"Vec<{rust_type(element)}>"
        case ast.Subscript(value=ast.Name(id="Required" | "ReadOnly"), slice=element):
            return rust_type(element)
        case ast.Subscript(value=ast.Name(id="Literal")):
            return "String"
        case _:
            raise ValueError(f"Unsupported annotation: {ast.unparse(annotation)}")


def generate_types(source, revision):
    declarations = {
        node.name: node for node in ast.parse(source).body if isinstance(node, ast.ClassDef)
    }
    lines = [
        "// Generated by third_party/litellm/generate_protocol_types.py.",
        f"// Source: BerriAI/litellm {revision}, {SOURCE}.",
        "// Upstream license: third_party/litellm/LICENSE.",
        "",
        "use serde::Serialize;",
        "use serde_json::Value;",
    ]
    for name, fields in FIELDS.items():
        declaration = declarations[name]
        annotations = {
            member.target.id: member.annotation
            for member in declaration.body
            if isinstance(member, ast.AnnAssign)
        }
        total = all(
            keyword.arg != "total" or keyword.value.value for keyword in declaration.keywords
        )
        lines.extend([
            "",
            "#[derive(Default, Serialize)]",
            '#[serde(rename_all = "camelCase")]',
            f"pub(super) struct {name} {{",
        ])
        for field in fields:
            annotation = annotations[field]
            required = total or (
                isinstance(annotation, ast.Subscript)
                and isinstance(annotation.value, ast.Name)
                and annotation.value.id == "Required"
            )
            field_name = re.sub(r"(?<=[a-z])(?=[A-Z])", "_", field).lower()
            if (name, field) in REST_FIELDS:
                field_name, field_type, required = REST_FIELDS[name, field]
            else:
                field_type = rust_type(annotation)
            if not required:
                lines.append('    #[serde(skip_serializing_if = "Option::is_none")]')
                field_type = f"Option<{field_type}>"
            lines.append(f"    pub(super) {field_name}: {field_type},")
        lines.append("}")
    return "\n".join(lines) + "\n"


def generate_reasoning_defaults(constants, model_catalog):
    defaults = {}
    for statement in ast.parse(constants).body:
        if isinstance(statement, ast.Assign) and len(statement.targets) == 1:
            target = statement.targets[0]
        elif isinstance(statement, ast.AnnAssign):
            target = statement.target
        else:
            continue
        if isinstance(target, ast.Name) and target.id in THINKING_BUDGETS:
            defaults[target.id] = ast.literal_eval(statement.value.args[1])
    lines = [""]
    for upstream, rust in THINKING_BUDGETS.items():
        lines.append(f"pub(super) const {rust}: i64 = {defaults[upstream]};")

    gemini = {
        name.removeprefix("gemini/"): capabilities
        for name, capabilities in model_catalog.items()
        if name.startswith("gemini/")
    }
    for name, field, value in [
        ("MODELS_WITHOUT_MINIMAL", "supports_minimal_reasoning_effort", False),
        ("MODELS_WITH_XHIGH", "supports_xhigh_reasoning_effort", True),
    ]:
        lines.extend(["", f"pub(super) const {name}: &[&str] = &["])
        for model, capabilities in sorted(gemini.items()):
            if capabilities.get(field) is value:
                lines.append(f"    {json.dumps(model)},")
        lines.append("];")
    return "\n".join(lines) + "\n"


def generate_claude_capabilities(model_catalog, revision):
    lines = [
        "// Generated by third_party/litellm/generate_protocol_types.py.",
        f"// Source: BerriAI/litellm {revision}, model_prices_and_context_window.json.",
        "",
        "use super::claude_reasoning::ClaudeThinking;",
        "",
        "pub(super) const CLAUDE_THINKING: &[(&str, ClaudeThinking)] = &[",
    ]
    for name, model in sorted(model_catalog.items()):
        if (
            not name.startswith("claude-")
            or model.get("litellm_provider") != "anthropic"
            or model.get("supports_reasoning") is not True
        ):
            continue
        if model.get("supports_adaptive_thinking") is True:
            supports_xhigh = model.get("supports_xhigh_reasoning_effort") is True
            always_on = model.get("thinking_always_on") is True
            explicit_disable = (
                model.get("thinking_on_by_default") is True and not always_on
            )
            profile = (
                "ClaudeThinking::Adaptive { "
                f"supports_xhigh: {str(supports_xhigh).lower()}, "
                f"disable_with_thinking_field: {str(explicit_disable).lower()}, "
                f"always_on: {str(always_on).lower()} }}"
            )
        else:
            profile = "ClaudeThinking::Legacy"
        lines.append(f"    ({json.dumps(name)}, {profile}),")
    lines.append("];")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path, help="local LiteLLM git checkout")
    parser.add_argument("--check", action="store_true", help="compare without writing files")
    args = parser.parse_args()
    checkout = args.checkout.resolve()
    manifest = CRATE.parent / "bamboo-litellm-llms-types" / "Cargo.toml"
    revision = tomllib.loads(manifest.read_text())["package"]["metadata"]["upstream"]["rev"]

    def read_upstream(path):
        return subprocess.check_output(
            ["git", "-C", str(checkout), "show", f"{revision}:{path}"], text=True
        )

    model_catalog = json.loads(read_upstream("model_prices_and_context_window.json"))
    outputs = {
        CRATE / "src/providers/gemini/litellm/wire.rs":
            generate_types(read_upstream(SOURCE), revision) + generate_reasoning_defaults(
            read_upstream("litellm/constants.py"),
            model_catalog,
        ),
        CRATE / "src/providers/anthropic/litellm/capabilities.rs":
            generate_claude_capabilities(model_catalog, revision),
    }
    for path, source in outputs.items():
        generated = subprocess.run(
            ["rustfmt", "--edition", "2021", "--emit", "stdout"],
            input=source, text=True, check=True, stdout=subprocess.PIPE,
        ).stdout
        if args.check:
            if path.read_text() != generated:
                parser.error(f"{path.relative_to(CRATE)} differs from the pinned source {revision}")
        else:
            path.write_text(generated)


if __name__ == "__main__":
    main()
